const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}

const nombre = String(body.nombre || '').trim();
const telefono = String(body.telefono || '').trim();
const servicio = String(body.servicio || '').trim();
const fecha = String(body.fecha || '').trim();
const hora = String(body.hora || '').trim();
const notas = String(body.notas || '').trim();

const DURACIONES = {
  'Revision': 30, 'Limpieza dental': 45, 'Empaste': 45,
  'Extraccion': 30, 'Blanqueamiento dental': 60,
  'Consulta ortodoncia': 30, 'Consulta implantes': 30, 'Endodoncia': 60
};
const duracion = DURACIONES[servicio] || 30;

const fechaInicio = new Date(`${fecha}T${hora}:00`);
const fechaFin = new Date(fechaInicio.getTime() + duracion * 60000);

const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const diaSemana = diasSemana[fechaInicio.getDay()];
const diaMes = fechaInicio.getDate();
const mes = meses[fechaInicio.getMonth()];

const descripcion = `Paciente: ${nombre}\nTeléfono: ${telefono}\nServicio: ${servicio}\nDuración: ${duracion} min${notas ? '\nNotas: ' + notas : ''}\nCreado por: Recepcionista IA Sara`;

return [{ json: {
  nombre, telefono, servicio, fecha, hora, notas, duracion,
  fechaInicio: fechaInicio.toISOString(),
  fechaFin: fechaFin.toISOString(),
  tituloEvento: `${nombre} - ${servicio}`,
  descripcion, diaSemana, diaMes, mes
}}];

const gcal = $('Google Calendar - Crear Evento').first().json;
const datos = $('Parsear Argumentos').first().json;
return [{ json: { ...datos, calendar_event_id: gcal.id || '' }}];

const datos = $('Añadir Calendar Event ID').first().json;
const gcal = $('Google Calendar - Crear Evento').first().json;
if (gcal.id) {
  return [{ json: {
    confirmado: true,
    id_cita: gcal.id,
    mensaje_confirmacion: `Cita confirmada. Te esperamos el ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora} para tu ${datos.servicio.toLowerCase()}. Recibirás la confirmación por WhatsApp.`
  }}];
}
return [{ json: {
  confirmado: false,
  error: 'calendar_error',
  mensaje: 'Ha habido un problema al crear la cita. ¿Quieres que lo intentemos de nuevo?'
}}];
